<script lang="ts">
 import {onMount} from 'svelte';import {api,websocketUrl} from '../lib/api.js';import {chooseContext,type WorkbenchState} from '../lib/workbench-state.js';import FolderTree from '@lucide/svelte/icons/folder-tree';import Search from '@lucide/svelte/icons/search';import SquareTerminal from '@lucide/svelte/icons/square-terminal';import ChartNoAxesCombined from '@lucide/svelte/icons/chart-no-axes-combined';import Settings from '@lucide/svelte/icons/settings';import ScanSearch from '@lucide/svelte/icons/scan-search';import RefreshCw from '@lucide/svelte/icons/refresh-cw';import Map from '@lucide/svelte/icons/map';import MoreHorizontal from '@lucide/svelte/icons/more-horizontal';import Play from '@lucide/svelte/icons/play';import FolderOpen from '@lucide/svelte/icons/folder-open';
 export let state:WorkbenchState;let contexts:any[]=[];let selected='local';let status='Discovering FNGK…';let repository='/workspace';let activeRail='explorer';let overflow='';const sockets=new Set<WebSocket>();
 async function load(){state.setConnection({phase:'checking',message:'Discovering installed FNGK…'});try{const value=await api<any>('/api/contexts');contexts=value.contexts;selected=chooseContext(contexts,state.snapshot());state.setContext(selected,false);if(value.state.compatible){status=`${value.state.profile??'default'} · ${value.state.version}`;state.setConnection({phase:'connected',message:`Connected to ${value.state.profile??'default'}`,profile:value.state.profile,version:value.state.version});}else{status=value.state.reason??'FNGK unavailable';state.setConnection({phase:value.state.login==='required'?'authentication-required':'unavailable',message:status,profile:value.state.profile,version:value.state.version});}}catch(error){status=(error as Error).message;contexts=[{id:'local',name:'Atlas process host (not FNGK)',kind:'local',online:true}];selected='local';state.setContext('local',false);state.setConnection({phase:'unavailable',message:status});}}
 function choose(id:string){selected=id;state.setContext(id);window.dispatchEvent(new CustomEvent('atlas:context',{detail:id}));}
 function scan(){const socket=new WebSocket(websocketUrl(`/api/discovery/scan?contextId=${encodeURIComponent(selected)}`));let failed=false;sockets.add(socket);status='Scanning host…';socket.onmessage=e=>{const v=JSON.parse(e.data);if(v.type==='error'){failed=true;status=v.message??v.code;}state.appendActivity(`${v.type} · ${v.scanned??''}`)};socket.onclose=()=>{sockets.delete(socket);if(!failed){status='Scan complete';window.dispatchEvent(new Event('atlas:graph-refresh'))}}}
 function analyze(){if(!repository.trim())return;const socket=new WebSocket(websocketUrl(`/api/analysis/repository?contextId=${encodeURIComponent(selected)}&path=${encodeURIComponent(repository)}`));let completed=false,failed=false;sockets.add(socket);status='Analyzing repository…';socket.onmessage=e=>{const v=JSON.parse(e.data);if(v.type==='error'){failed=true;status=v.message??v.code}state.appendActivity(`${v.type} · ${v.index?.summary?.functions??v.nodes?.length??''}`);if(v.type==='analysis_complete'){completed=true;status=`${v.index.summary.functions} functions mapped`;window.dispatchEvent(new Event('atlas:graph-refresh'))}};socket.onclose=()=>{sockets.delete(socket);if(!completed&&!failed)status='Analysis stopped'}}
 function rail(name:string){activeRail=name;window.dispatchEvent(new CustomEvent('atlas:rail',{detail:name}));if(name==='terminal')window.dispatchEvent(new Event('atlas:open-terminal'))}
 function deviceAction(action:string,id:string){choose(id);overflow='';if(action==='terminal')window.dispatchEvent(new Event('atlas:open-terminal'));if(action==='scan')scan();if(action==='files')window.dispatchEvent(new CustomEvent('atlas:focus-files'))}
 onMount(()=>{void load();const runScan=()=>scan(),runAnalyze=()=>analyze(),focusSearch=()=>rail('search'),focusExplorer=()=>rail('explorer');window.addEventListener('atlas:scan',runScan);window.addEventListener('atlas:analyze',runAnalyze);window.addEventListener('atlas:focus-search',focusSearch);window.addEventListener('atlas:focus-files',focusExplorer);return()=>{for(const socket of sockets)socket.close();sockets.clear();window.removeEventListener('atlas:scan',runScan);window.removeEventListener('atlas:analyze',runAnalyze);window.removeEventListener('atlas:focus-search',focusSearch);window.removeEventListener('atlas:focus-files',focusExplorer)}});
 onMount(()=>{void api<any>('/api/contexts').then(value=>{const local=value.contexts?.find((item:any)=>item.id==='local');if(local?.workspaceRoot)repository=local.workspaceRoot}).catch(()=>{})});
</script>
<aside class="navigator"><div class="brand"><div class="brand-mark">Σ</div><div><strong>ATLAS</strong><small>FNGK workbench</small></div></div>{#if activeRail==='explorer'}<div class="section-title">CONTEXTS</div>{#each contexts as item}<div class:active={item.id===selected} class="context-row"><button class="context" onclick={()=>choose(item.id)}><span class:online={item.online}></span><div><b>{item.name}</b><small>{item.kind??'machine'} · {item.online?'reachable':'offline'}</small></div></button>{#if item.kind==='fngk-device'}<div class="context-actions"><button title="Open terminal" aria-label="Open terminal" onclick={()=>deviceAction('terminal',item.id)}><Play size={13}/></button><button title="Open filesystem" aria-label="Open filesystem" onclick={()=>deviceAction('files',item.id)}><FolderOpen size={13}/></button><button title="More device actions" aria-label="More device actions" onclick={()=>overflow=overflow===item.id?'':item.id}><MoreHorizontal size={14}/></button>{#if overflow===item.id}<div class="context-overflow"><button onclick={()=>deviceAction('scan',item.id)}><ScanSearch size={13}/>Scan device</button><button onclick={()=>{choose(item.id);rail('coverage')}}><ChartNoAxesCombined size={13}/>Coverage</button></div>{/if}</div>{/if}</div>{/each}<div class="section-title">REPOSITORY</div><div class="repository"><input bind:value={repository} aria-label="Repository path" placeholder="/path/to/repository"><button title="Map the selected repository into the Atlas graph" onclick={analyze}><Map size={14}/>Map code</button></div><div class="navigator-actions"><button title="Scan the selected context using its effective FNGK access" onclick={scan}><ScanSearch size={14}/>Scan selected host</button><button title="Reload the FNGK namespace" onclick={load}><RefreshCw size={14}/>Refresh namespace</button></div>{:else if activeRail==='search'}<div class="section-title">SEARCH</div><div class="repository"><input aria-label="Search Atlas" placeholder="Search files, symbols, processes…" oninput={(event)=>window.dispatchEvent(new CustomEvent('atlas:search',{detail:(event.currentTarget as HTMLInputElement).value}))}></div><div class="context-status">Search is shared across the active context, graph, files, and sessions.</div>{:else if activeRail==='terminal'}<div class="section-title">TERMINAL SESSIONS</div><div class="context-status">Open the terminal rail to attach automatically to the selected Device.</div>{:else if activeRail==='coverage'}<div class="section-title">COVERAGE & PROBLEMS</div><div class="context-status">Coverage, CRAP, stale evidence, and parser problems appear here.</div>{:else}<div class="section-title">SETTINGS</div><div class="context-status">Workbench layout and FNGK context settings.</div>{/if}<div class="context-status">{status}</div><div class="navigator-spacer"></div><nav class="rail" aria-label="Atlas views"><button title="Explorer" aria-label="Explorer" class:active={activeRail==='explorer'} onclick={()=>rail('explorer')}><FolderTree size={18}/></button><button title="Search" aria-label="Search" class:active={activeRail==='search'} onclick={()=>rail('search')}><Search size={18}/></button><button title="Terminal sessions" aria-label="Terminal sessions" class:active={activeRail==='terminal'} onclick={()=>rail('terminal')}><SquareTerminal size={18}/></button><button title="Coverage and problems" aria-label="Coverage and problems" class:active={activeRail==='coverage'} onclick={()=>rail('coverage')}><ChartNoAxesCombined size={18}/></button><button title="Settings" aria-label="Settings" class:active={activeRail==='settings'} onclick={()=>rail('settings')}><Settings size={18}/></button></nav></aside>
